-/* A real <figure> (its own accessible group, named by the sr-only <figcaption> at its end) — the
-   railroad diagram and FIRST/FOLLOW chips read as one unit to assistive tech, not two unrelated
-   pieces of content that happen to sit next to each other. `margin: 0` overrides the UA default
-   <figure> indent (`1em 40px`), which this class never wanted even back when it was a plain div. */
 .gramaire__output {
-  margin: 0;
   padding: 12px 16px;
 }
-/* Visually hidden but present for assistive tech — the standard clip-based pattern (kept on-screen
-   at a 1x1px, unclipped-by-overflow position rather than `display: none`/`visibility: hidden`,
-   both of which screen readers also skip). */
-.gramaire__sr-only {
-  position: absolute;
-  width: 1px;
-  height: 1px;
-  padding: 0;
-  margin: -1px;
-  overflow: hidden;
-  clip: rect(0, 0, 0, 0);
-  white-space: nowrap;
-  border: 0;
-}
